    def on_core_version_selected(self, current):
        if  current is not None:
            CoreFileNameJar = current.text()
            print(CoreFileNameJar)
            
            try:
                max_mem = int(self.MaxMemText.text())
                min_mem = int(self.MinMemText.text())
                self.LaunchButton.clicked.connect(partial(StartServer, max_mem, min_mem, CoreFileNameJar))
            except ValueError:
                print("内存设置必须为整数!")

        else:
            CoreFileNameJar = ""
            print("错误! 未选择服务端版本!")
