class ConsoleWindow(QtWidgets.QDialog):
    def __init__(self, parent=None):
        super(ConsoleWindow, self).__init__(parent)
        self.text_browser = QtWidgets.QTextBrowser(self)
        layout = QtWidgets.QVBoxLayout(self)
        layout.addWidget(self.text_browser)
        self.setLayout(layout)
    
    def write(self, text):
        self.text_browser.append(text)
    
    def flush(self):
        pass

# 重定向 stdout 和 stderr
def redirect_output(console_window):
    sys.stdout = console_window
    sys.stderr = console_window

# 修改 StartServer 函数以使用新的 ConsoleWindow
def StartServer(MaximumMemory, MinimumMemory, CoreFileNameJar:str):
    # 创建并显示控制台窗口
    MaximumMemory = str(MaximumMemory)
    MinimumMemory = str(MinimumMemory)
    print(MaximumMemory)
    print(MinimumMemory)
    print(type(MaximumMemory))
    print(type(MinimumMemory))
    
    try:
        console_window = ConsoleWindow()
        console_window.show()
        redirect_output(console_window)
        # MaximumMemory = int(Ui_MainWindow.MaxMemText.text())
        # MinimumMemory = int(Ui_MainWindow.MinMemText.text())
        
        # 开服命令整合
        # command = f"java -Xmx{MaximumMemory}M -Xms{MinimumMemory}M -jar {CoreFileName}.jar -Dcom.mojang.eula.agree=true"
        # CoreFileNameJar = CoreFileName + ".jar"
        if not os.path.isfile(CoreFileNameJar):
            raise FileNotFoundError(f"指定的 JAR 文件未找到: {CoreFileNameJar}")
        
        # 使用 subprocess.Popen 代替 os.system 以实现实时输出重定向
        os.system("java -version")

        process = QtCore.QProcess()
        process.setProgram("java")
        process.setArguments(["-Xmx%sM" % MaximumMemory,"-Xms%sM" % MinimumMemory,"-jar", CoreFileNameJar])
        process.readyReadStandardOutput.connect(lambda: console_window.text_browser.append(process.readAllStandardOutput().data().decode()))
        process.readyReadStandardError.connect(lambda: console_window.text_browser.append(process.readAllStandardError().data().decode()))
        process.start()
    except Exception as e:
        console_window.text_browser.append(f"启动服务器发生了错误: {e}")

